import { Choice, Button } from "../novakit";
import { PAYROLL_DELAY_REPORTED_ON, REVIEW_DATES, formatDate } from "../advance/salaryAdvance";
import SegmentedControl from "./SegmentedControl";
import DateSteps from "./DateSteps";
import AcceptOutcome, { ACCEPT_OUTCOMES } from "./AcceptOutcome";

const PERSONA_OPTIONS = [
  { id: "A", label: "Persona A", description: "Salary into NovaPay, limit Rs 10,000." },
  { id: "B", label: "Persona B", description: "Salary into a bank. 7 Jul only." },
];

// What each reviewer date shows. The dates themselves come from the module.
const DATE_NAMES = {
  S1: "Accept flow (S1–S9)",
  S10: "Reminder (S10)",
  S11: "Payday (S11)",
  S12: "Late (S12)",
};

// The cause isn't a reviewer choice (decided in chat 5): the late path is shown for
// "salary didn't arrive", the scenario default. Named in "Now showing" from payday on.
const CAUSE_LABELS = {
  salary_not_arrived: "Salary didn't arrive",
  salary_short: "Salary arrived short",
  balance_dropped: "Balance dropped",
  salary_moved_to_bank: "Salary moved to a bank",
};

const DATE_STEPS = REVIEW_DATES.map((d) => ({ id: d.scenario, date: formatDate(d.date), name: DATE_NAMES[d.scenario] }));

/**
 * Reviewer tools: one panel beside the phone frame, never inside it, on a neutral-100
 * surface so it never passes for product UI. It sets data, not screens. App builds
 * everything from the module's scenario().
 *
 * Order: what the phone shows now, then who, when, whether a payroll delay was
 * reported, and what happens after Accept. Groups that only apply on some dates (`options`, from
 * scenarioOptions; After Accept only on 7 Jul with persona A) sit below the ones that
 * always show, so their arrival never moves anything above them. A hidden choice keeps
 * its selection. Persona B is 7 Jul only: B has no advance. Not part of the product, so
 * it may start with a selection. "Start again" returns to 7 Jul, persona A, nothing
 * accepted.
 */
export default function ReviewerState({ value, options, outcome, onOutcomeChange, showOutcome, onChange, onStartAgain }) {
  const set = (patch) => onChange({ ...value, ...patch });
  const isA = value.persona === "A";
  const step = DATE_STEPS.find((s) => s.id === value.scenario);

  // Two lines: when and what (the state), then who and anything else that shapes it.
  const summary = isA ? `${step.date} · ${step.name}` : `${formatDate(REVIEW_DATES[0].date)} · Needs verification (S2)`;
  const detail = [
    `Persona ${value.persona}`,
    isA && options.reason ? CAUSE_LABELS[value.reason] : null,
    isA && options.payroll_delay && value.payroll_delay ? `Payroll delay reported on ${formatDate(PAYROLL_DELAY_REPORTED_ON)}` : null,
    showOutcome ? `After Accept: ${ACCEPT_OUTCOMES.find((o) => o.id === outcome).label}` : null,
  ]
    .filter(Boolean)
    .join(" · ");

  return (
    <section aria-labelledby="reviewer-tools-title" className="w-80 rounded-lg border border-neutral-300 bg-neutral-100 p-4">
      <h2 id="reviewer-tools-title" className="text-body font-semibold text-neutral-900">
        Reviewer tools
      </h2>
      <p className="text-caption text-neutral-700">Not part of the app.</p>

      {/* Groups are 16px apart; inside a group, 8px or less. */}
      <div className="mt-4 space-y-4">
        <div className="rounded-md bg-white p-3" aria-live="polite">
          <p className="text-caption text-neutral-700">Now showing</p>
          <p className="text-body font-semibold text-neutral-900">{summary}</p>
          <p className="text-caption text-neutral-700">{detail}</p>
        </div>

        <SegmentedControl
          legend="Who"
          name="review-persona"
          options={PERSONA_OPTIONS}
          value={value.persona}
          onChange={(persona) => set({ persona })}
        />

        {isA ? (
          <DateSteps
            legend="When"
            name="review-date"
            steps={DATE_STEPS}
            value={value.scenario}
            onChange={(scenario) => set({ scenario })}
          />
        ) : null}

        {isA && options.payroll_delay ? (
          <Choice
            type="checkbox"
            checked={value.payroll_delay}
            onChange={(e) => set({ payroll_delay: e.target.checked })}
            label={`Payroll delay reported on ${formatDate(PAYROLL_DELAY_REPORTED_ON)}`}
          />
        ) : null}

        {showOutcome ? <AcceptOutcome value={outcome} onChange={onOutcomeChange} /> : null}
      </div>

      <div className="mt-4 border-t border-neutral-300 pt-4">
        <Button variant="secondary" onClick={onStartAgain}>
          Start again
        </Button>
      </div>
    </section>
  );
}
import SegmentedControl from "./SegmentedControl";

// What happens after "Accept" is tapped. The prototype has no backend, so the reviewer picks.
export const ACCEPT_OUTCOMES = [
  { id: "works", label: "Works", description: "Goes to the receipt." },
  { id: "network", label: "Fails once", description: "Network failure: the first attempt fails; Try again works." },
  {
    id: "reduced",
    label: "Lower amount",
    description: "From Rs 10,000 only: we can offer Rs 5,000 instead (S7). Rs 5,000 has no lower tier, so it works.",
  },
];

/**
 * Reviewer scaffolding: the "After Accept" section of the reviewer panel (ReviewerState).
 * Not part of the product, so it may start with a selection. "Fails once" fails the first
 * attempt of each run (it resets when the flow goes back home). Shown only where Accept
 * can be reached: 7 Jul, persona A.
 */
export default function AcceptOutcome({ value, onChange }) {
  return (
    <SegmentedControl
      legend="After Accept"
      name="accept-outcome"
      options={ACCEPT_OUTCOMES}
      value={value}
      onChange={onChange}
    />
  );
}
import { useEffect, useMemo, useRef, useState } from "react";
import ChooseAmount from "./screens/ChooseAmount";
import ReviewAccept from "./screens/ReviewAccept";
import Receipt from "./screens/Receipt";
import Home from "./screens/Home";
import AdvanceDetails from "./screens/AdvanceDetails";
import PayYourselfPlaceholder from "./screens/PayYourselfPlaceholder";
import ReviewerState from "./review/ReviewerState";
import {
  acceptTerms,
  getActivity,
  getOffer,
  getReminders,
  getStatus,
  getTerms,
  getWallet,
  reducePayout,
  scenario,
  scenarioOptions,
} from "./advance/salaryAdvance";

const PROCESSING_MS = 1500; // simulated time to confirm an acceptance

/**
 * NovaPay prototype in a mobile frame. Screens are built from NovaKit Lite
 * (./novakit) and read every amount and date from the salary-advance module.
 */

// Mobile frame: a fixed 390×844 device. The AppBar and action area stay put; main scrolls.
// The action area is the sticky bottom of the frame: a screen puts its main action there
// so it stays visible while the content scrolls. Nothing is shown when it's empty.
// `overlay` is for things that sit above the content, like a Toast. It's placed at the
// bottom of the content area, just above the action area, never over the actions.
// `sheet` is for a modal BottomSheet: it covers the whole frame, actions included.
//
// Every screen gets the same arrival: the page title becomes `title`, and after a screen
// change focus moves to the screen's <h1>, so a screen reader announces where you are.
// The first screen on page load keeps the browser's own focus.
// A reviewer change also goes home, but quietly: focus stays in the reviewer control.
let hasChangedScreen = false; // set by App's navigation, never during render
let quietArrival = false; // set by a reviewer change; any other navigation clears it

function PhoneFrame({ title, appBar, actions = null, overlay = null, sheet = null, children }) {
  const frameRef = useRef(null);

  useEffect(() => {
    document.title = title;
    if (hasChangedScreen && !quietArrival) frameRef.current?.querySelector("h1")?.focus();
  }, [title]);

  return (
    <div
      ref={frameRef}
      className="relative w-[390px] h-[844px] shrink-0 flex flex-col bg-neutral-50 rounded-[28px] shadow-xl overflow-hidden border border-neutral-300"
    >
      {appBar}

      {/* The overlay sits at the bottom of the content area, so it never covers the actions. */}
      <div className="relative flex-1 min-h-0 flex flex-col">
        <main className="phone-scroll flex-1 min-h-0 overflow-y-auto p-4 space-y-4">{children}</main>
        {overlay}
      </div>

      {actions ? (
        <footer className="shrink-0 bg-white border-t border-neutral-200 p-4 space-y-3">{actions}</footer>
      ) : null}

      {sheet}
    </div>
  );
}

const START_REVIEW = { persona: "A", scenario: "S1", reason: "salary_not_arrived", payroll_delay: false };

export default function App() {
  const [review, setReview] = useState(START_REVIEW);
  const [screen, setScreen] = useState("home");
  const [amount, setAmount] = useState(null);
  const [liveAdvance, setLiveAdvance] = useState(null); // accepted in the live flow on 7 Jul
  const [reducedTerms, setReducedTerms] = useState(null);
  const [outcome, setOutcome] = useState("works");
  const failedOnce = useRef(new Set()); // terms ids whose first attempt has already failed

  // Everything the screens see comes from the module's scenario(): persona B is S2 (7 Jul
  // only); persona A on 7 Jul is the live flow, with whatever the reviewer accepted; later
  // dates use the scenario's Rs 10,000 advance, because each cause's balances are built
  // around Rs 10,300 owed.
  const reviewId = review.persona === "B" ? "S2" : review.scenario;
  const reviewOptions = scenarioOptions(reviewId, { reason: review.reason });
  const scene = useMemo(
    () => scenario(reviewId, { reason: review.reason, payroll_delay: review.payroll_delay }),
    [reviewId, review.reason, review.payroll_delay]
  );
  const { persona, today } = scene;
  const isLive = reviewId === "S1";
  const advance = isLive ? liveAdvance : scene.advance;
  // The offer knows about the open advance: one advance at a time (module rule).
  const offer = getOffer(persona, today, advance);
  const terms = amount != null ? getTerms(persona, amount, today) : null;
  const status = advance ? getStatus(advance, today) : null;
  // S11's "Hide this message" on Home: kept for this failed attempt until the app is opened
  // again (a reload clears this state) or the reviewer starts again. Not saved anywhere.
  const [hiddenNotice, setHiddenNotice] = useState(null);
  const noticeKey = status?.last_attempt ? `${advance.id}:${status.last_attempt.date}` : null;

  // Only an eligible offer reaches the offer screens (S3, S4, S7). Anyone else (persona B,
  // or someone with an open advance) is sent to home. The terms screens need terms; without
  // them they go back to the amounts. Screens after accepting need the advance.
  // Mid-flow, the advance is set only after accepting, so S4 and S7 stay reachable until then.
  const OFFER_SCREENS = ["chooseAmount", "terms", "reduced"];
  let current = screen;
  if (OFFER_SCREENS.includes(screen) && offer.eligibility !== "eligible") current = "home";
  else if (screen === "terms" && terms == null) current = "chooseAmount";
  else if (screen === "reduced" && reducedTerms == null) current = "chooseAmount";
  else if (["receipt", "advanceDetails", "payYourself"].includes(screen) && advance == null) current = "home";

  function go(next) {
    hasChangedScreen = true;
    quietArrival = false;
    setScreen(next);
  }

  function leaveToHome() {
    setAmount(null); // nothing is pre-selected next time
    setReducedTerms(null);
    failedOnce.current.clear(); // the next run's first attempt fails again
    go("home");
  }

  // Reviewer only: new data starts from home, and focus stays in the reviewer control.
  function changeReview(next) {
    leaveToHome();
    quietArrival = true;
    setReview(next);
  }

  // Reviewer only: back to 7 Jul, persona A, nothing accepted, to run the flow again.
  function startAgain() {
    setLiveAdvance(null);
    setHiddenNotice(null);
    changeReview({ ...review, persona: "A", scenario: "S1" });
  }

  function changeOutcome(next) {
    failedOnce.current.clear(); // a new choice starts from a first attempt again
    setOutcome(next);
  }

  // Simulates sending the acceptance. Resolves to "failed" (the screen shows the failure and
  // stays), or moves to the receipt or the reduced payout and resolves to "moved".
  // The screen passes what was actually ticked; the module refuses without it.
  // acceptTerms is idempotent: a second tap returns the same advance, never a second one.
  async function accept(forTerms, consent) {
    await new Promise((resolve) => setTimeout(resolve, PROCESSING_MS));
    if (outcome === "network" && !failedOnce.current.has(forTerms.id)) {
      failedOnce.current.add(forTerms.id);
      return "failed";
    }
    if (outcome === "reduced" && forTerms.reduced_from == null) {
      const lower = reducePayout(forTerms);
      if (lower) {
        setReducedTerms(lower);
        go("reduced");
        return "moved";
      }
    }
    const result = acceptTerms(forTerms, consent, today);
    if (result.error) return "failed"; // unreachable: the screen only calls this once the box is ticked
    setLiveAdvance(result);
    go("receipt");
    return "moved";
  }

  return (
    <div className="min-h-screen w-full flex justify-center items-start py-6">
      {/* The phone is centred on the page. Reviewer controls (src/review/) hang off its right
          side, never inside it, and come after it in the DOM so Tab reaches the phone first. */}
      <div className="relative">
        {current === "home" ? (
          <Home
            Frame={PhoneFrame}
            today={today}
            persona={persona}
            offer={offer}
            wallet={getWallet(persona, advance, today)}
            activity={getActivity(persona, advance, today)}
            advance={advance}
            status={status}
            noticeHidden={noticeKey != null && hiddenNotice === noticeKey}
            onHideNotice={() => setHiddenNotice(noticeKey)}
            onStartAdvance={() => go("chooseAmount")}
            onStartVerification={() => go("verifySalary")}
            onSeeAdvance={() => go("advanceDetails")}
          />
        ) : null}

        {current === "chooseAmount" ? (
          <ChooseAmount
            Frame={PhoneFrame}
            offer={offer}
            amount={amount}
            onAmountChange={setAmount}
            onContinue={() => go("terms")}
            onLeave={leaveToHome}
          />
        ) : null}

        {current === "terms" ? (
          <ReviewAccept
            key={terms.id}
            Frame={PhoneFrame}
            terms={terms}
            onAccept={(consent) => accept(terms, consent)}
            onChangeAmount={() => go("chooseAmount")}
            onLeave={leaveToHome}
          />
        ) : null}

        {/* S7: the same screen in its reduced-payout form, with fresh, unticked consent. */}
        {current === "reduced" ? (
          <ReviewAccept
            key={reducedTerms.id}
            Frame={PhoneFrame}
            terms={reducedTerms}
            onAccept={(consent) => accept(reducedTerms, consent)}
            onLeave={leaveToHome}
          />
        ) : null}

        {current === "receipt" ? <Receipt Frame={PhoneFrame} advance={advance} onDone={leaveToHome} /> : null}

        {current === "advanceDetails" ? (
          <AdvanceDetails
            Frame={PhoneFrame}
            advance={advance}
            status={status}
            reminders={getReminders(advance, today)}
            onBack={() => go("home")}
            onPayYourself={() => go("payYourself")}
            // "My salary is late": the same review state as the reviewer checkbox, so the
            // scenario reports it on 2 Aug (my Assumption). Stays on this screen.
            onReportPayrollDelay={() => setReview({ ...review, payroll_delay: true })}
          />
        ) : null}

        {/* S2's "Start verification": the same labelled placeholder, with its own words. */}
        {current === "verifySalary" ? (
          <PayYourselfPlaceholder
            Frame={PhoneFrame}
            onBack={() => go("home")}
            title="Verify your salary"
            backLabel="Back to home"
            heading="Placeholder: verify your salary"
            line="This screen isn't built yet. Nothing has been shared."
          />
        ) : null}

        {current === "payYourself" ? (
          <PayYourselfPlaceholder Frame={PhoneFrame} onBack={() => go("advanceDetails")} />
        ) : null}

        <aside aria-label="Reviewer controls" className="absolute left-full top-0 ml-6">
          <ReviewerState
            value={review}
            options={reviewOptions}
            onChange={changeReview}
            onStartAgain={startAgain}
            // Accept can only be reached on 7 Jul with persona A.
            showOutcome={isLive}
            outcome={outcome}
            onOutcomeChange={changeOutcome}
          />
        </aside>
      </div>
    </div>
  );
}
# NovaKit Lite

A small slice of **NovaPay's coded design system** — the starter for the AI-First Product Designer case study. It gives you design tokens, a handful of components, and a running mobile-framed app to build on.

> Read this and the components carefully — but treat the system as a **starting point, not gospel**. Real design systems are messier than their docs suggest: some things are missing, some are inconsistent, and some shouldn't be reused as-is. Part of your job is to notice that.

## Run it

```bash
npm install
npm run dev
```

Then open the local URL Vite prints. The app renders inside a ~390px mobile frame — keep your work mobile-first.

```bash
npm run build   # production build (also a quick way to check nothing is broken)
npm run check   # fails on hex colours, arbitrary values or default Tailwind colours in src/, and checks the salary-advance module
```

## What's in here

```
src/
  novakit/            # the design system — build from these
    Button.jsx        # primary | secondary · md | lg · optional second line · loading
    TextField.jsx     # default · focused · disabled
    Card.jsx          # surface container · tones: default | attention | danger
    Panel.jsx         # deprecated alias of Card
    ListRow.jsx       # icon · title/subtitle · trailing amount · optional wrap
    AppBar.jsx        # title (the screen's h1) + optional back with a label
    BottomSheet.jsx   # modal dialog sheet: title, focus handling, Escape, Close
    Toast.jsx         # transient message · success | neutral
    AmountText.jsx    # formats PKR amounts (and formatAmount for strings)
    Choice.jsx        # checkbox or radio with label, description, blocked reason
    index.js          # barrel export -> import { Button } from "./novakit"
  advance/
    salaryAdvance.js  # the one source of truth for salary-advance money and dates
  screens/            # Home (S1, S9), ChooseAmount (S3), ReviewAccept (S4–S7), Receipt (S8), AdvanceDetails, advanceParts (shared rows and late details)
  review/             # reviewer controls shown beside the phone, never inside it
  App.jsx             # phone frame and routing
  index.css           # Tailwind entry
scripts/              # npm run check: token check and module check, plus the allow-list
tailwind.config.js    # design tokens (colors, radius, type scale, elevation)
DESIGN_SYSTEM.md      # log of every token or component change
```

Tokens live in `tailwind.config.js` (e.g. `bg-brand`, `bg-brand-50`, `text-attention-600`, `text-neutral-700`, `rounded-md`, `shadow-card`, `text-title`). The palette is intentionally generous — a full brand (indigo) ramp, an amber `attention` ramp for states that need attention (soft background, dark text, never a solid fill), a `danger` colour only for a failed event, and a layered neutral scale — so you have room to make real aesthetic choices. Use it with restraint. Build new work from tokens and existing components; extend the system only where you genuinely need to, and keep design and code in sync.

## Your task (summary)

Design and build the **first-time salary-advance experience** — offer → terms/total cost → accept — plus at least one path where the news isn't good or simple (declined/ineligible, over-limit, or a late/missed repayment). See the full brief and `PRODUCT_REFERENCE.md` for the product details (tiers, fees, decline reasons, repayment states).

## How to submit

Share a runnable prototype: a **pull request** against this repo is preferred (work on a branch or fork), but a deployed link or repo is fine too — as long as it runs. Add your short writeup (Google Doc or PDF) and your AI process (prompt log or a 5–10 min screen recording, including one AI output you rejected and why). Don't lose a weekend over this — it's sized for about 6 hours.
| R | Reviewer state switcher | Jump between S1–S13 outside the phone frame | — | **Scaffolding, not NovaKit.** It sits on the backdrop, so the allow-list or check may need to know about it (Q7) | Outside a fixed 390×844 frame. Needs an allow-list change, which I approve before it's made. *Updated 17 Oct (chat 5):* built as a basic data control, `src/review/ReviewerState.jsx` (Card, Choice, Button), above "after Accept". It sets persona, date (7 Jul, 25 Jul, 28 Jul, 2 Aug, 20 Aug; *20 Aug dropped later in chat 5 with S13*), the not-collected cause and payroll delay; App builds everything from `scenario()`. No allow-list change was needed. A change returns to Home with focus left in the control; choices that don't apply are hidden; B is 7 Jul only. URLs, notes and a narrow-screen drawer come later. *Restructured 17 Oct (chat 5):* one "Reviewer tools" panel on neutral-100 with a "Now showing" summary, review-only `SegmentedControl` and `DateSteps` (logged in `DESIGN_SYSTEM.md`), After Accept merged in. *Simplified 17 Oct (chat 5):* the not-collected cause is no longer a reviewer choice (the late path shows "salary didn't arrive"), the payroll delay is one checkbox, and the panel is `w-80` (320px): 746px at most, inside the 844px phone, but it needs a window about 1,060px wide (the narrow-screen drawer comes later) |

