  const set = (patch) => onChange({ ...value, ...patch });
  const isA = value.persona === "A";
  const step = DATE_STEPS.find((s) => s.id === value.scenario);

  // Two lines: when and what (the state), then who and anything else that shapes it.
  const summary = isA ? `${step.date} · ${step.name}` : `${formatDate(REVIEW_DATES[0].date)} · Needs verification (S2)`;
  const detail = [
    `Persona ${value.persona}`,
    isA && options.reason ? CAUSE_LABELS[value.reason] : null,
    isA && options.payroll_delay && value.payroll_delay ? `Payroll delay reported on ${formatDate(PAYROLL_DELAY_REPORTED_ON)}` : null,
    showOutcome ? `After Accept: ${ACCEPT_OUTCOMES.find((o) => o.id === outcome).label}` : null,
  ]
    .filter(Boolean)
    .join(" · ");

  return (
    <section aria-labelledby="reviewer-tools-title" className="w-80 rounded-lg border border-neutral-300 bg-neutral-100 p-4">
      <h2 id="reviewer-tools-title" className="text-body font-semibold text-neutral-900">
        Reviewer tools
      </h2>
      <p className="text-caption text-neutral-700">Not part of the app.</p>

      {/* Groups are 16px apart; inside a group, 8px or less. */}
      <div className="mt-4 space-y-4">
        <div className="rounded-md bg-white p-3" aria-live="polite">
          <p className="text-caption text-neutral-700">Now showing</p>
          <p className="text-body font-semibold text-neutral-900">{summary}</p>
          <p className="text-caption text-neutral-700">{detail}</p>
        </div>

        <SegmentedControl
          legend="Who"
          name="review-persona"
          options={PERSONA_OPTIONS}
          value={value.persona}
          onChange={(persona) => set({ persona })}
        />

        {isA ? (
          <DateSteps
            legend="When"
            name="review-date"
            steps={DATE_STEPS}
            value={value.scenario}
            onChange={(scenario) => set({ scenario })}
          />
        ) : null}

        {isA && options.payroll_delay ? (
          <Choice
            type="checkbox"
            checked={value.payroll_delay}
            onChange={(e) => set({ payroll_delay: e.target.checked })}
            label={`Payroll delay reported on ${formatDate(PAYROLL_DELAY_REPORTED_ON)}`}
          />
        ) : null}

        {showOutcome ? <AcceptOutcome value={outcome} onChange={onOutcomeChange} /> : null}
      </div>

      <div className="mt-4 border-t border-neutral-300 pt-4">
        <Button variant="secondary" onClick={onStartAgain}>
          Start again
        </Button>
      </div>
    </section>
  );
}
import SegmentedControl from "./SegmentedControl";

// What happens after "Accept" is tapped. The prototype has no backend, so the reviewer picks.
export const ACCEPT_OUTCOMES = [
  { id: "works", label: "Works", description: "Goes to the receipt." },
  { id: "network", label: "Fails once", description: "Network failure: the first attempt fails; Try again works." },
  {
    id: "reduced",
    label: "Lower amount",
    description: "From Rs 10,000 only: we can offer Rs 5,000 instead (S7). Rs 5,000 has no lower tier, so it works.",
  },
];

/**
 * Reviewer scaffolding: the "After Accept" section of the reviewer panel (ReviewerState).
 * Not part of the product, so it may start with a selection. "Fails once" fails the first
 * attempt of each run (it resets when the flow goes back home). Shown only where Accept
 * can be reached: 7 Jul, persona A.
 */
export default function AcceptOutcome({ value, onChange }) {
  return (
    <SegmentedControl
      legend="After Accept"
