await (async () => {
const wait = ms => new Promise(r => setTimeout(r, ms));
const cur = () => [...document.querySelectorAll('aside [aria-current]')].map(a=>a.getAttribute('href')).join() + '|' + ([...document.querySelectorAll('input[name=accept-outcome]')].find(i=>i.checked)?.value ?? 'none') + '|' + (document.querySelector('aside li.bg-brand-50') ? 'S5-S7 marked' : '');
const btn = t => [...document.querySelectorAll('button')].find(b => b.innerText.trim().startsWith(t));
const log = [];
document.querySelector('.phone-scroll input[type=checkbox]').click();
btn('Accept').click(); await wait(300); log.push('processing: ' + btn('Accept')?.innerText + ' ' + cur());
await wait(1700); log.push('after: ' + document.querySelector('[role=alert]')?.innerText.slice(0,60) + ' ' + cur());
btn('Try again').click(); await wait(2000); log.push('retry: ' + document.querySelector('h1').innerText + ' ' + cur());
btn('Done').click(); await wait(300); log.push('done: ' + document.querySelector('h1').innerText + ' ' + cur());
// Lower amount
[...document.querySelectorAll('input[name=accept-outcome]')].find(i=>i.value==='reduced').click(); await wait(300);
log.push('lower: ' + document.querySelector('h1').innerText + ' ' + cur());
document.querySelector('.phone-scroll input[type=checkbox]').click();
btn('Accept').click(); await wait(2000); log.push('S7: ' + document.querySelector('.phone-scroll').innerText.slice(0,60).replace(/\s+/g,' ') + ' ' + cur());
// S12, report delay
[...document.querySelectorAll('aside a')].find(a=>a.getAttribute('href')==='?state=S12').click(); await wait(300);
btn('See details').click(); await wait(300); log.push('details: ' + cur());
btn('My salary is late').click(); await wait(300); log.push('reported: ' + cur() + ' ' + document.querySelector('[role=status]')?.innerText.slice(0,50));
btn('Back')?.click(); 
return log.join('\n');
})()

