await (async () => {
const errs = [];
for (const id of ["S1","S4","S6","S7","S9","S11","S12-delay"]) {
  const f = document.createElement('iframe'); f.style.cssText = 'position:fixed;left:-3000px;width:1400px;height:1000px';
  f.src = `/?state=${id}`; document.body.append(f);
  await new Promise(r => f.onload = () => { f.contentWindow.addEventListener('error', e => errs.push(id + ': ' + e.message)); r(); });
  await new Promise(r => setTimeout(r, 700));
  // jump through every entry inside the frame to exercise the scroll effect
  for (const a of f.contentDocument.querySelectorAll('aside a')) { a.click(); await new Promise(r => setTimeout(r, 60)); }
  for (const i of f.contentDocument.querySelectorAll('aside input[name=accept-outcome]')) { i.click(); await new Promise(r => setTimeout(r, 60)); }
  if (!f.contentDocument.querySelector('aside nav')) errs.push(id + ': panel missing');
  f.remove();
}
return errs.length ? errs.join('\n') : 'no errors';
})()

