  const pr = panel.getBoundingClientRect();
  const toggle = d.querySelector('[aria-controls=reviewer-controls-panel]');
  const row = { w, phone: [Math.round(phone.left), Math.round(phone.top), Math.round(phone.width), Math.round(phone.height)], panelShown: getComputedStyle(panel).display !== 'none', panel: [Math.round(pr.left), Math.round(pr.top), Math.round(pr.width), Math.round(pr.height)], toggleShown: toggle.getClientRects().length > 0, hScroll: d.documentElement.scrollWidth - win.innerWidth, pairCentre: Math.round(((phone.left + (pr.width ? pr.right : phone.right)) / 2) - w / 2) };
  if (row.toggleShown) {
    toggle.click(); await new Promise(r => setTimeout(r, 200));
    const p2 = panel.getBoundingClientRect(), ph2 = d.querySelector('[class*="h-[844px]"]').getBoundingClientRect();
    row.opened = { expanded: toggle.getAttribute('aria-expanded'), panel: [Math.round(p2.top), Math.round(p2.height)], phoneTopAfter: Math.round(ph2.top), overlap: p2.bottom > ph2.top };
    const link = [...d.querySelectorAll('#reviewer-controls-panel a')].find(a => a.getAttribute('href') === '?state=S12');
    link.click(); await new Promise(r => setTimeout(r, 200));
    row.afterJump = { closed: getComputedStyle(panel).display === 'none', expanded: toggle.getAttribute('aria-expanded'), focusOnToggle: d.activeElement === toggle, h1: d.querySelector('h1').innerText, url: win.location.search };
  }
  // tab order: first tabbable element and where the reviewer controls come
  const tabbables = [...d.querySelectorAll('a[href], button, input')].filter(e => e.getClientRects().length && !e.disabled);
  row.firstTab = tabbables[0]?.innerText.trim().slice(0, 20) || tabbables[0]?.tagName;
  row.reviewerIndexInTab = tabbables.findIndex(e => e.closest('aside'));
  row.phoneTabbables = tabbables.filter(e => !e.closest('aside')).length;
  out.push(JSON.stringify(row));
  f.remove();
}
return out.join('\n');
})()

