await (async () => {
const out = [];
for (const [w, h] of [[1400, 1000], [1024, 900], [768, 900], [767, 900], [375, 812]]) {
  const f = document.createElement('iframe'); f.style.cssText = `position:fixed;left:-5000px;top:0;width:${w}px;height:${h}px;border:0`;
  f.src = '/?state=S12-delay'; document.body.append(f);
  await new Promise(r => f.onload = r); await new Promise(r => setTimeout(r, 700));
  const d = f.contentDocument, win = f.contentWindow;
  const phone = d.querySelector('[class*="h-[844px]"]').getBoundingClientRect();
  const panel = d.getElementById('reviewer-controls-panel');
  const pr = panel.getBoundingClientRect();
  const nav = panel.querySelector('nav'); const cur = nav.querySelector('[data-current]')?.getBoundingClientRect(); const nr = nav.getBoundingClientRect();
  const toggle = d.querySelector('[aria-controls=reviewer-controls-panel]');
  const row = { w, phone: [Math.round(phone.left), Math.round(phone.top), Math.round(phone.height)], panel: pr.width ? [Math.round(pr.left), Math.round(pr.top), Math.round(pr.width), Math.round(pr.height)] : 'hidden', docH: d.documentElement.scrollHeight, hScroll: d.documentElement.scrollWidth > d.documentElement.clientWidth, centre: pr.width ? Math.round((phone.left + pr.right) / 2 - d.documentElement.clientWidth / 2) : Math.round((phone.left + phone.right) / 2 - d.documentElement.clientWidth / 2), currentInView: cur ? cur.top >= nr.top && cur.bottom <= nr.bottom : null, toggle: toggle.getClientRects().length > 0 };
  if (row.toggle) {
    toggle.click(); await new Promise(r => setTimeout(r, 300));
    const c2 = nav.querySelector('[data-current]').getBoundingClientRect(), n2 = nav.getBoundingClientRect();
    row.openCurrentInView = c2.top >= n2.top && c2.bottom <= n2.bottom;
    toggle.click(); await new Promise(r => setTimeout(r, 100));
    row.closedAgain = getComputedStyle(panel).display === 'none';
  }
  out.push(JSON.stringify(row)); f.remove();
}
return out.join('\n');
})()

